#!/usr/bin/env bash
# Every version of dist/bitchat.service this project has shipped, by SHA-256,
# so install.sh and uninstall.sh can tell a unit bitchat wrote (any version)
# from one you changed. The binaries are built locally, so for them only the
# install record counts.
#
#   dist/gen-known-hashes.sh > dist/known-hashes.tsv   regenerate
#   dist/gen-known-hashes.sh --check                   is this checkout's unit listed,
#                                                      and is every listed hash one
#                                                      this generates? (CI runs it)
#
# Covers every commit on main that touched dist/bitchat.service (users
# install from main, not only tags), every tag, and the working tree. Not
# `--all`: stashes and fetched PR refs aren't anything users installed.
# Run it and commit the result whenever dist/bitchat.service changes.
#
# Line format: <sha256>\t<label>\t<logical path>, tab-separated. The logical
# path is `unit`; the label is the short commit that first shipped the bytes.
set -euo pipefail
cd "$(dirname "$0")/.."

hash_stdin() { sha256sum | cut -d' ' -f1; }

# main, or the remote's main in a CI checkout that has no local branch.
main_ref() {
  local r
  for r in main origin/main; do git rev-parse --verify -q "$r^{commit}" >/dev/null && { echo "$r"; return 0; }; done
  echo "no 'main' or 'origin/main' here (fetch with full history)" >&2
  return 1
}

generate() {
  local c main
  main="$(main_ref)" || exit 1
  {
    while IFS= read -r c; do
      git cat-file -e "$c:dist/bitchat.service" 2>/dev/null || continue
      printf '%s\t%s\t%s\n' "$(git show "$c:dist/bitchat.service" | hash_stdin)" "$(git rev-parse --short "$c")" unit
    done < <(git log --reverse --format=%H "$main" --tags -- dist/bitchat.service)
    printf '%s\t%s\t%s\n' "$(hash_stdin <dist/bitchat.service)" "worktree" unit
  } | awk -F'\t' '!seen[$1 FS $3]++' | LC_ALL=C sort -t $'\t' -k3,3 -k1,1 -s
}

case "${1:-}" in
  "")
    echo "# generated by dist/gen-known-hashes.sh; do not edit. sha256, first label, logical path."
    generate
    ;;
  --check)
    [[ -f dist/known-hashes.tsv ]] || { echo "dist/known-hashes.tsv is missing" >&2; exit 1; }
    h="$(hash_stdin <dist/bitchat.service)"
    if ! awk -F'\t' -v h="$h" '$1 == h && $3 == "unit" { found = 1 } END { exit !found }' dist/known-hashes.tsv; then
      echo "dist/bitchat.service ($h) isn't listed in dist/known-hashes.tsv." >&2
      echo "Run dist/gen-known-hashes.sh > dist/known-hashes.tsv and commit it." >&2
      exit 1
    fi
    # Every listed hash must be one this generates (labels may differ): a
    # hash added by hand would make some other file count as bitchat's.
    fresh="$(generate | cut -f1,3 | LC_ALL=C sort -u)" || exit 1
    extra="$(grep -v '^#' dist/known-hashes.tsv | cut -f1,3 | LC_ALL=C sort -u | LC_ALL=C comm -23 - <(printf '%s\n' "$fresh"))"
    if [[ -n $extra ]]; then
      echo "dist/known-hashes.tsv lists hashes no version of dist/bitchat.service on main, a tag or this tree has:" >&2
      printf '  %s\n' "$extra" >&2
      exit 1
    fi
    missing="$(printf '%s\n' "$fresh" | LC_ALL=C comm -23 - <(grep -v '^#' dist/known-hashes.tsv | cut -f1,3 | LC_ALL=C sort -u))"
    [[ -z $missing ]] || { echo "note: older versions not listed (regenerate to include them):"; printf '  %s\n' "$missing"; }
    echo "known-hashes.tsv covers this checkout's unit and lists nothing else."
    ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac
